-- Modulo 68 EvaluacionDesempeno: ciclos de evaluacion, competencias ponderadas, evaluaciones y calificaciones.
-- Spec: docs/specs/modulo68-evaluacion-desempeno-backend.md (§4).

CREATE TABLE "CiclosEvaluacion" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Codigo" character varying(20) NOT NULL,
    "Nombre" character varying(100) NOT NULL,
    "Periodo" character varying(20) NOT NULL,
    "FechaInicioPeriodo" date NOT NULL,
    "FechaFinPeriodo" date NOT NULL,
    "FechaApertura" date NOT NULL,
    "FechaCierre" date NOT NULL,
    "Estado" character varying(20) NOT NULL,
    CONSTRAINT "PK_CiclosEvaluacion" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_CiclosEvaluacion_Periodo" CHECK ("Periodo" IN ('Semestral', 'Anual')),
    CONSTRAINT "CK_CiclosEvaluacion_Estado" CHECK ("Estado" IN ('Configuracion', 'Abierto', 'Cerrado')),
    CONSTRAINT "CK_CiclosEvaluacion_Fechas" CHECK ("FechaFinPeriodo" > "FechaInicioPeriodo" AND "FechaCierre" > "FechaApertura")
);
CREATE UNIQUE INDEX "IX_CiclosEvaluacion_Codigo" ON "CiclosEvaluacion" ("Codigo");

CREATE TABLE "CompetenciasEvaluacion" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "CicloEvaluacionId" integer NOT NULL,
    "Nombre" character varying(100) NOT NULL,
    "Descripcion" character varying(300),
    "Peso" numeric(5,2) NOT NULL,
    CONSTRAINT "PK_CompetenciasEvaluacion" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CompetenciasEvaluacion_CiclosEvaluacion_CicloEvaluacionId" FOREIGN KEY ("CicloEvaluacionId") REFERENCES "CiclosEvaluacion" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_CompetenciasEvaluacion_Peso" CHECK ("Peso" > 0 AND "Peso" <= 100)
);
CREATE UNIQUE INDEX "IX_CompetenciasEvaluacion_CicloEvaluacionId_Nombre" ON "CompetenciasEvaluacion" ("CicloEvaluacionId", "Nombre");

CREATE TABLE "Evaluaciones" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "CicloEvaluacionId" integer NOT NULL,
    "EmpleadoId" integer NOT NULL,
    "EvaluadorId" integer NOT NULL,
    "Estado" character varying(20) NOT NULL,
    "Comentario" character varying(500),
    "PuntajeFinal" numeric(4,2),
    "FechaEnvio" timestamp with time zone,
    "FechaCierre" timestamp with time zone,
    CONSTRAINT "PK_Evaluaciones" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Evaluaciones_CiclosEvaluacion_CicloEvaluacionId" FOREIGN KEY ("CicloEvaluacionId") REFERENCES "CiclosEvaluacion" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Evaluaciones_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Evaluaciones_Empleados_EvaluadorId" FOREIGN KEY ("EvaluadorId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_Evaluaciones_Estado" CHECK ("Estado" IN ('Borrador', 'Enviada', 'Cerrada')),
    CONSTRAINT "CK_Evaluaciones_Evaluador" CHECK ("EmpleadoId" <> "EvaluadorId")
);
CREATE UNIQUE INDEX "IX_Evaluaciones_CicloEvaluacionId_EmpleadoId" ON "Evaluaciones" ("CicloEvaluacionId", "EmpleadoId");
CREATE INDEX "IX_Evaluaciones_EmpleadoId" ON "Evaluaciones" ("EmpleadoId");
CREATE INDEX "IX_Evaluaciones_EvaluadorId" ON "Evaluaciones" ("EvaluadorId");

CREATE TABLE "CalificacionesEvaluacion" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "EvaluacionId" integer NOT NULL,
    "CompetenciaEvaluacionId" integer NOT NULL,
    "Calificacion" integer NOT NULL,
    CONSTRAINT "PK_CalificacionesEvaluacion" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CalificacionesEvaluacion_Evaluaciones_EvaluacionId" FOREIGN KEY ("EvaluacionId") REFERENCES "Evaluaciones" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_CalificacionesEvaluacion_CompetenciasEvaluacion_CompetenciaEvaluacionId" FOREIGN KEY ("CompetenciaEvaluacionId") REFERENCES "CompetenciasEvaluacion" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_CalificacionesEvaluacion_Calificacion" CHECK ("Calificacion" BETWEEN 1 AND 5)
);
CREATE UNIQUE INDEX "IX_CalificacionesEvaluacion_EvaluacionId_CompetenciaEvaluacionId" ON "CalificacionesEvaluacion" ("EvaluacionId", "CompetenciaEvaluacionId");
CREATE INDEX "IX_CalificacionesEvaluacion_CompetenciaEvaluacionId" ON "CalificacionesEvaluacion" ("CompetenciaEvaluacionId");
